functions.fn_add_member_to_group_conversation:
CREATE OR REPLACE FUNCTION public.fn_add_member_to_group_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_conv_id uuid; v_current_ids uuid[];
BEGIN
    IF NEW.user_id IS NULL THEN RETURN NEW; END IF;
    IF TG_OP = 'INSERT' AND NEW.status <> 'approved' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND (OLD.status = 'approved' OR NEW.status <> 'approved') THEN RETURN NEW; END IF;
    SELECT messenger_conversation_id INTO v_conv_id FROM commander_home_groups WHERE id = NEW.group_id;
    IF v_conv_id IS NULL THEN RETURN NEW; END IF;
    INSERT INTO messenger_participants (conversation_id, user_id, role, joined_at)
    VALUES (v_conv_id, NEW.user_id, CASE WHEN NEW.role IN ('owner','admin') THEN 'admin' ELSE 'member' END, NOW())
    ON CONFLICT DO NOTHING;
    SELECT participant_ids INTO v_current_ids FROM conversations WHERE id = v_conv_id;
    IF NOT (NEW.user_id = ANY(v_current_ids)) THEN
        UPDATE conversations SET participant_ids = array_append(participant_ids, NEW.user_id), updated_at = NOW() WHERE id = v_conv_id;
    END IF;
    RETURN NEW;
END;
$function$

functions.fn_append_video_playlist:
CREATE OR REPLACE FUNCTION public.fn_append_video_playlist(p_playlist_id uuid, p_video_id text, p_title text, p_source text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_owner uuid; v_position integer;
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
    IF p_video_id IS NULL OR p_video_id !~ '^[A-Za-z0-9_-]{11}$' THEN RAISE EXCEPTION 'Invalid video id' USING ERRCODE = '22023'; END IF;
    SELECT user_id INTO v_owner FROM public.video_playlists WHERE id = p_playlist_id FOR UPDATE;
    IF v_owner IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Playlist unavailable' USING ERRCODE = '42501'; END IF;
    IF EXISTS (SELECT 1 FROM public.video_playlist_items WHERE playlist_id = p_playlist_id AND video_id = p_video_id) THEN RETURN true; END IF;
    SELECT COALESCE(max(sort_order), -1) + 1 INTO v_position FROM public.video_playlist_items WHERE playlist_id = p_playlist_id;
    INSERT INTO public.video_playlist_items(playlist_id,video_id,video_title,video_source,sort_order)
      VALUES(p_playlist_id,p_video_id,left(p_title,300),left(p_source,80),v_position);
    RETURN true;
END $function$

functions.fn_create_home_group_conversation:
CREATE OR REPLACE FUNCTION public.fn_create_home_group_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_conv_id uuid;
BEGIN
    INSERT INTO conversations (participant_ids, created_by, category, is_pinned, is_read_only)
    VALUES (ARRAY[NEW.owner_id]::uuid[], NEW.owner_id, 'home_group', false, false)
    RETURNING id INTO v_conv_id;
    UPDATE commander_home_groups SET messenger_conversation_id = v_conv_id WHERE id = NEW.id;
    INSERT INTO messenger_participants (conversation_id, user_id, role, joined_at)
    VALUES (v_conv_id, NEW.owner_id, 'admin', NOW()) ON CONFLICT DO NOTHING;
    RETURN NEW;
END; $function$

functions.fn_remove_member_from_group_conversation:
CREATE OR REPLACE FUNCTION public.fn_remove_member_from_group_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_conv_id uuid; v_user_id uuid; v_group_id uuid;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status = 'banned' AND OLD.status <> 'banned' THEN
        v_user_id := NEW.user_id; v_group_id := NEW.group_id;
    ELSIF TG_OP = 'DELETE' THEN
        v_user_id := OLD.user_id; v_group_id := OLD.group_id;
    ELSE RETURN COALESCE(NEW, OLD);
    END IF;
    SELECT messenger_conversation_id INTO v_conv_id FROM commander_home_groups WHERE id = v_group_id;
    IF v_conv_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
    DELETE FROM messenger_participants WHERE conversation_id = v_conv_id AND user_id = v_user_id;
    UPDATE conversations SET participant_ids = array_remove(participant_ids, v_user_id), updated_at = NOW() WHERE id = v_conv_id;
    RETURN COALESCE(NEW, OLD);
END; $function$

functions.fn_reorder_video_playlist:
CREATE OR REPLACE FUNCTION public.fn_reorder_video_playlist(p_playlist_id uuid, p_expected_video_ids text[], p_video_ids text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_owner uuid; v_actual text[];
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
    SELECT user_id INTO v_owner FROM public.video_playlists WHERE id = p_playlist_id FOR UPDATE;
    IF v_owner IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Playlist unavailable' USING ERRCODE = '42501'; END IF;
    IF p_video_ids IS NULL OR p_expected_video_ids IS NULL OR cardinality(p_video_ids) > 500
        OR array_position(p_video_ids, NULL) IS NOT NULL
        OR cardinality(p_video_ids) <> (SELECT count(DISTINCT id) FROM unnest(p_video_ids) id)
    THEN RAISE EXCEPTION 'Invalid playlist order' USING ERRCODE = '22023'; END IF;
    PERFORM id FROM public.video_playlist_items WHERE playlist_id = p_playlist_id FOR UPDATE;
    SELECT COALESCE(array_agg(video_id ORDER BY sort_order, created_at, id), ARRAY[]::text[])
      INTO v_actual FROM public.video_playlist_items WHERE playlist_id = p_playlist_id;
    IF v_actual IS DISTINCT FROM p_expected_video_ids THEN RAISE EXCEPTION 'Playlist changed; reload before reordering' USING ERRCODE = 'PT409'; END IF;
    IF cardinality(v_actual) <> cardinality(p_video_ids)
       OR NOT (v_actual @> p_video_ids AND p_video_ids @> v_actual)
    THEN RAISE EXCEPTION 'Playlist membership changed' USING ERRCODE = '22023'; END IF;
    UPDATE public.video_playlist_items item SET sort_order = ordered.position - 1
      FROM unnest(p_video_ids) WITH ORDINALITY AS ordered(video_id, position)
      WHERE item.playlist_id = p_playlist_id AND item.video_id = ordered.video_id;
    RETURN true;
END $function$

functions.fn_sync_home_game_vouch_count:
CREATE OR REPLACE FUNCTION public.fn_sync_home_game_vouch_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.commander_home_groups
           SET vouch_count = vouch_count + 1
         WHERE id = NEW.group_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.commander_home_groups
           SET vouch_count = GREATEST(0, vouch_count - 1)
         WHERE id = OLD.group_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$
